25	Behaviour.specify(".secret", "secret-button", 0, function (e) {
26	  var secretUpdateBtn = e.querySelector(".secret-update-btn");
27	  if (secretUpdateBtn === null) {
28	    return;
29	  }
30	
31	  var id = "secret-" + iota++;
32	  var name = e.getAttribute("data-name");
33	  var placeholder = e.getAttribute("data-placeholder");
34	  var prompt = e.getAttribute("data-prompt");
35	
36	  var appendSecretInput = function () {
37	    var textarea = document.createElement("textarea");
38	    textarea.setAttribute("id", id);
39	    textarea.setAttribute("name", name);
40	    if (placeholder !== null && placeholder !== "") {
41	      textarea.setAttribute("placeholder", placeholder);
42	    }
43	    var secretInput = document.createElement("div");
44	    secretInput.setAttribute("class", "secret-input");
45	    secretInput.appendChild(textarea);
46	    e.appendChild(secretInput);
47	  };
48	
49	  var clearSecretValue = function () {
50	    var secretValue = e.querySelector('input[type="hidden"]');
51	    if (secretValue !== null) {
52	      secretValue.parentNode.removeChild(secretValue);
53	    }
54	  };
55	
56	  var replaceUpdateButton = function () {
57	    var secretLabel = document.createElement("label");
58	    secretLabel.setAttribute("for", id);
59	    secretLabel.appendChild(document.createTextNode(prompt));
60	    secretUpdateBtn.parentNode.replaceChild(secretLabel, secretUpdateBtn);
61	  };
62	
63	  var removeSecretLegendLabel = function () {
64	    var secretLegend = e.querySelector(".secret-legend");
65	    var secretLegendText = secretLegend.querySelector("span");
66	    if (secretLegendText !== null) {
67	      secretLegend.removeChild(secretLegendText);
68	    }
69	  };
70	
71	  secretUpdateBtn.onclick = function () {
72	    appendSecretInput();
73	    clearSecretValue();
74	    replaceUpdateButton();
75	    removeSecretLegendLabel();
76	  };
77	});
